query:
-- Get Company project ID
SET @company_id = (SELECT id FROM projects WHERE title = 'Company' LIMIT 1);

-- Add tags for Company
INSERT INTO projectTags (projectId, tagId)
SELECT @company_id, id FROM tags WHERE name IN ('Stephen Sondheim', '2019', 'University Theatre', 'Musical Theatre', 'New York City', 'Relationships')
ON DUPLICATE KEY UPDATE projectId = projectId;

